async () => {
  // Execute only after independently accepted signup source is active.
  const account = 'b03e6ea242724c05eb97eb732cceb21d';
  const host = 'bee-validation-20260909.klappy.workers.dev';
  const worker = 'bee-validation-20260909';
  const ownerId = '8fc54e03-24c8-4c02-9376-7c639a3ca94e';
  const emailId = '5ae63959-05d5-45a7-a9bd-237c271245c0';
  const expectedVersion = '__REVIEWED_SIGNUP_VERSION__';
  // Independently accepted cost boundary: provider blocks new logins at the
  // existing purchased-seat ceiling. Actual plan and free seats are unknown
  // because subscriptions GET returned 403. This helper cannot buy seats.
  const billingReceipt = '2026-09-10 independent review: existing capacity only; https://developers.cloudflare.com/cloudflare-one/team-and-resources/users/seat-management/';
  const appFields = ['allow_authenticate_via_warp','allow_iframe','allowed_idps','app_launcher_visible','auto_redirect_to_identity','cors_headers','custom_deny_message','custom_deny_url','custom_non_identity_deny_url','custom_pages','destinations','domain','eager_redirect_cookie_setting','enable_binding_cookie','http_only_cookie_attribute','logo_url','mfa_config','name','oauth_configuration','options_preflight_bypass','path_cookie_attribute','read_service_tokens_from_header','same_site_cookie_attribute','scim_config','self_hosted_domains','service_auth_401_redirect','session_duration','skip_interstitial','tags','type','use_clientless_isolation_app_launcher_url'];
  const policyFields = ['precedence','approval_groups','approval_required','connection_rules','isolation_required','mfa_config','purpose_justification_prompt','purpose_justification_required','session_duration','decision','exclude','include','name','require'];
  const assert = (ok, label) => { if (!ok) throw Error(label); };
  const cloneFields = (value, fields) => Object.fromEntries(fields.filter(k => value[k] !== undefined).map(k => [k, value[k]]));
  const ordered = x => Array.isArray(x) ? x.map(ordered) : x && typeof x === 'object' ? Object.fromEntries(Object.keys(x).sort().map(k=>[k,ordered(x[k])])) : x;
  const canon = x => JSON.stringify(ordered(x));
  let phase = 'preflight';
  const written = [];
  async function api(method, path, body) {
    const r = await fetch('https://api.cloudflare.com/client/v4/accounts/' + account + path, {method, redirect:'manual', headers:body ? {'Content-Type':'application/json'} : {}, body:body ? JSON.stringify(body) : undefined});
    const j = await r.json();
    assert(r.ok && j.success, 'provider ' + method + ' HTTP ' + r.status);
    return j.result;
  }
  try {
    assert(accountId === account, 'account mismatch');
    assert(!expectedVersion.startsWith('__'), 'reviewed version not bound');
    assert(!billingReceipt.startsWith('__'), 'account seat allowance not verified');
    const deployments = await api('GET', '/workers/scripts/' + worker + '/deployments');
    assert(deployments.deployments[0].versions.length === 1 && deployments.deployments[0].versions[0].version_id === expectedVersion, 'reviewed source not active');
    const beforeApps = await api('GET', '/access/apps?per_page=100');
    assert(beforeApps.length === 5, 'Access inventory drift');
    const preserved = {};
    for (const app of beforeApps.filter(a => a.id !== ownerId && a.id !== emailId)) {
      preserved[app.id] = {app:await api('GET', '/access/apps/' + app.id), policies:await api('GET', '/access/apps/' + app.id + '/policies')};
    }
    const production = canon(await api('GET', '/workers/scripts/bee-ai-auth-mcp/deployments'));
    const owner = await api('GET', '/access/apps/' + ownerId);
    const ownerPolicies = await api('GET', '/access/apps/' + ownerId + '/policies');
    const email = await api('GET', '/access/apps/' + emailId);
    const emailPolicies = await api('GET', '/access/apps/' + emailId + '/policies');
    assert(ownerPolicies.length === 1 && ownerPolicies[0].decision === 'allow' && ownerPolicies[0].include.length === 1 && !!ownerPolicies[0].include[0].email, 'owner policy shape');
    assert(emailPolicies.length === 1 && emailPolicies[0].decision === 'deny' && emailPolicies[0].include.length === 1 && !!emailPolicies[0].include[0].everyone, 'email deny shape');
    assert(email.allowed_idps.length === 1 && email.allowed_idps[0] === 'c47d1caf-ecad-4abc-8c66-17c96c9ff5fd', 'OTP IdP mismatch');
    assert([host,host + '/admin'].includes(owner.domain) && [host + '/authorize/email',host + '/signup'].includes(email.domain), 'old target drift');
    assert(owner.aud === '11479aab4d4f4d70aec0d82b1c04bbc1972e179a9cadee257c483f5fbebb2a75' && owner.allowed_idps.length === 1 && owner.allowed_idps[0] === 'c47d1caf-ecad-4abc-8c66-17c96c9ff5fd' && owner.session_duration === '1h' && owner.http_only_cookie_attribute === true, 'owner preserved security settings');
    const ownerBody = cloneFields(owner, appFields);
    ownerBody.policies = ownerPolicies.map(p => ({id:p.id, ...cloneFields(p, policyFields)}));
    ownerBody.domain = host + '/admin';
    ownerBody.destinations = ['/admin', '/admin/*'].map(path => ({type:'public', uri:host + path}));
    // Provider derives this deprecated projection from destinations on PUT.
    ownerBody.self_hosted_domains = ownerBody.destinations.map(d=>d.uri);
    phase = 'owner route';
    if(owner.domain === host) {
      await api('PUT', '/access/apps/' + ownerId, ownerBody);
      written.push('owner_app_destinations');
    }
    const ownerAfter = await api('GET', '/access/apps/' + ownerId);
    assert(canon(ownerAfter.destinations) === canon(ownerBody.destinations) && ownerAfter.aud === owner.aud, 'owner scope readback');
    assert(canon(cloneFields(ownerAfter, appFields)) === canon(cloneFields(ownerBody, appFields)), 'owner preserved settings mismatch');
    assert(canon(await api('GET', '/access/apps/' + ownerId + '/policies')) === canon(ownerPolicies), 'owner policy changed');
    const emailBody = cloneFields(email, appFields);
    emailBody.policies = emailPolicies.map(p => ({id:p.id, ...cloneFields(p, policyFields)}));
    emailBody.domain = host + '/signup';
    emailBody.destinations = ['/signup','/signup/*','/preview','/preview/*','/index.html','/authorize/email','/authorize/email/*'].map(path => ({type:'public', uri:host + path}));
    emailBody.self_hosted_domains = emailBody.destinations.map(d=>d.uri);
    phase = 'email routes';
    if(email.domain !== host + '/signup') {
      await api('PUT', '/access/apps/' + emailId, emailBody);
      written.push('email_app_destinations');
    }
    const emailAfter = await api('GET', '/access/apps/' + emailId);
    assert(canon(emailAfter.destinations) === canon(emailBody.destinations) && emailAfter.aud === email.aud, 'email scope readback');
    assert(canon(cloneFields(emailAfter, appFields)) === canon(cloneFields(emailBody, appFields)), 'email preserved settings mismatch');
    const denyRead = await api('GET', '/access/apps/' + emailId + '/policies');
    const semanticPolicies = ps => ps.map(p=>({id:p.id,...cloneFields(p,policyFields)}));
    assert(canon(semanticPolicies(denyRead)) === canon(semanticPolicies(emailPolicies)), 'deny changed before policy write');
    const policyBody = cloneFields(emailPolicies[0], policyFields);
    policyBody.decision = 'allow';
    policyBody.name = 'Verified email signup; application approval still required';
    phase = 'email OTP policy';
    await api('PUT', '/access/apps/' + emailId + '/policies/' + emailPolicies[0].id, policyBody);
    written.push('email_otp_allow');
    const finalPolicies = await api('GET', '/access/apps/' + emailId + '/policies');
    assert(finalPolicies.length === 1 && canon(cloneFields(finalPolicies[0], policyFields)) === canon(policyBody), 'email policy readback');
    phase = 'boundaries readback';
    for (const [id, state] of Object.entries(preserved)) {
      assert(canon(await api('GET', '/access/apps/' + id)) === canon(state.app), 'unrelated app changed');
      assert(canon(await api('GET', '/access/apps/' + id + '/policies')) === canon(state.policies), 'unrelated policy changed');
    }
    assert(canon(await api('GET', '/workers/scripts/bee-ai-auth-mcp/deployments')) === production, 'production changed');
    assert(canon(await api('GET', '/workers/scripts/' + worker + '/deployments')) === canon(deployments), 'unexpected deployment effect');
    return {accepted:true, observed:new Date().toISOString(), phase, written, version:expectedVersion, owner_app:ownerId, email_app:emailId, owner_policy_unchanged:true, email_otp_all:true, owner_paths:ownerBody.destinations.map(d=>d.uri), email_paths:emailBody.destinations.map(d=>d.uri), unrelated_access_unchanged:true, production_unchanged:true};
  } catch (e) {
    // Deliberately no provider bodies, identity values, or credentials in errors.
    return {accepted:false, phase, written, error:e.message};
  }
}

